package com.enterprisehub.domain;
import jakarta.persistence.*; import com.fasterxml.jackson.annotation.JsonIgnore;
@Entity @Table(name="employees") public class Employee { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) public Long id; @Column(nullable=false) public String name; @Column(nullable=false,unique=true) public String email; @JsonIgnore @Column(name="password_hash",nullable=false) public String passwordHash; @Column(nullable=false) public String role; @ManyToOne @JoinColumn(name="department_id") public Department department; @Column(nullable=false) public boolean active=true; protected Employee(){} public Employee(String name,String email,String hash,String role,Department department){this.name=name;this.email=email;this.passwordHash=hash;this.role=role;this.department=department;} }
